 try{const saved=JSON.parse(localStorage.getItem('optionpilot.premium.workspace')||'{}');if(Array.isArray(saved.ladderMetrics))chainMetrics=[...new Set<string>(saved.ladderMetrics.filter((k:any)=>typeof k==='string'&&Object.hasOwn(metricNames,k)))];}catch{}
