  const vals=[...valid.map((p:any)=>p.value),...levels.map(l=>l[1])],lo=Math.min(...vals),hi=Math.max(...vals),pad=Math.max((hi-lo)*.1,1),from=Date.parse(points[0].at),to=Date.parse(points.at(-1).at),x=(t:any)=>65+(Date.parse(t)-from)/Math.max(to-from,1000)*plotWidth,y=(v:number)=>270-(v-lo+pad)/(hi-lo+2*pad)*225;
  html+='<svg viewBox="0 0 ' +width+' 320" role="img" aria-label="'+esc(r.symbol+' '+r.strike+' '+r.type+' sampled premium reaction')+'">';
  for(let i=0;i<4;i++){const v=lo-pad+(hi-lo+2*pad)*i/3;html+='<line x1="65" x2="'+edge+'" y1="'+y(v)+'" y2="'+y(v)+'" stroke="#293e59"/><text x="58" y="'+(y(v)+4)+'" text-anchor="end" fill="#a5b8d1" font-size="12">'+fmt(v)+'</text>';}
  let prev:any=null;for(const p of points){if(p.value===null){prev=null;continue;}if(prev&&Date.parse(p.at)-Date.parse(prev.at)<=180000)html+='<line x1="'+x(prev.at)+'" x2="'+x(p.at)+'" y1="'+y(prev.value)+'" y2="'+y(p.value)+'" stroke="'+(r.type==='CE'?'#75eae0':'#ff8aad')+'" stroke-width="2.5"/>';html+='<circle cx="'+x(p.at)+'" cy="'+y(p.value)+'" r="2" fill="#edf8ff"><title>'+time(p.at)+' · '+fmt(p.value)+'</title></circle>';prev=p;}
  const labels=levels.map(l=>({label:l[0],value:l[1],color:l[2],actual:y(l[1]),pos:y(l[1])})).sort((a,b)=>a.pos-b.pos);for(let i=1;i<labels.length;i++)labels[i].pos=Math.max(labels[i].pos,labels[i-1].pos+19);if(labels.at(-1)?.pos>280){labels.at(-1).pos=280;for(let i=labels.length-2;i>=0;i--)labels[i].pos=Math.min(labels[i].pos,labels[i+1].pos-19);}
  if(width<600)for(const l of labels)html+='<line x1="65" x2="'+edge+'" y1="'+l.actual+'" y2="'+l.actual+'" stroke="'+l.color+'" stroke-dasharray="4 5"/>';
  if(width>=600)for(const l of labels)html+='<line x1="65" x2="'+edge+'" y1="'+l.actual+'" y2="'+l.actual+'" stroke="'+l.color+'" stroke-dasharray="4 5"/><path d="M'+edge+' '+l.actual+' L'+(edge+15)+' '+l.pos+'" fill="none" stroke="'+l.color+'"/><text x="'+(edge+20)+'" y="'+(l.pos+4)+'" fill="'+l.color+'" font-size="12">'+esc(l.label)+' '+fmt(l.value)+'</text>';
  $('pw-chart').innerHTML=html+'<text x="65" y="306" fill="#a5b8d1" font-size="12">'+time(points[0].at)+'</text><text x="'+edge+'" y="306" text-anchor="end" fill="#a5b8d1" font-size="12">'+time(points.at(-1).at)+'</text></svg>'+(width<600?'<div class="pw-chart-levels">'+levels.map(l=>'<span>'+esc(l[0])+' ₹'+fmt(l[1])+'</span>').join('')+'</div>':'');
